import java.util.*;

class Solution {
    public int commonFactors(int a, int b) {
        int smaller = Math.min(a, b);
        int larger = Math.max(a, b);
        Set<Integer> divisors = new HashSet<>();

        for (int factor = 1; factor * factor <= smaller; factor++) {
            if (smaller % factor == 0) {
                divisors.add(factor);
                divisors.add(smaller / factor);
            }
        }

        int count = 0;
        for (int factor : divisors) {
            if (larger % factor == 0) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int commonFactors(int a, int b) {
        int g = gcd(a, b);
        int count = 0;
        for (int factor = 1; factor * factor <= g; factor++) {
            if (g % factor == 0) {
                count++;
                if (factor != g / factor) {
                    count++;
                }
            }
        }
        return count;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int r = a % b;
            a = b;
            b = r;
        }
        return a;
    }
}

class Solution {
    public int commonFactors(int a, int b) {
        int g = gcd(a, b);
        int answer = 1;
        for (int prime = 2; prime * prime <= g; prime++) {
            if (g % prime != 0) {
                continue;
            }
            int exponent = 0;
            while (g % prime == 0) {
                g /= prime;
                exponent++;
            }
            answer *= exponent + 1;
        }
        if (g > 1) {
            answer *= 2;
        }
        return answer;
    }

    private int gcd(int a, int b) {
        while (b != 0) {
            int r = a % b;
            a = b;
            b = r;
        }
        return a;
    }
}
